<section class="shell page-intro"><a class="text-link" href="<?= e(url('reservations')) ?>">My reservations</a><h1>Reservation checkout.</h1><p>A temporary hold keeps your selected space while checkout is pending.</p></section>
<section class="shell booking-section">
<?php if ($pageData['errors']): ?><div class="form-errors" role="alert"><?php foreach ($pageData['errors'] as $error): ?><p><?= e($error) ?></p><?php endforeach; ?></div>
<?php elseif ($reservation=$pageData['reservation']):
$snapshot=json_decode($reservation['rate_snapshot'],true,64,JSON_THROW_ON_ERROR);
$label=static fn(string $timestamp):string=>(new DateTimeImmutable($timestamp,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('M j, Y · g:i A');
$live=$reservation['status']==='pending'&&$reservation['expires_at']&&$reservation['released_at']===null&&$reservation['expires_at']>$reservation['server_now'];
?>
<div class="booking-grid"><article class="content-card"><span class="eyebrow"><?= e(ucfirst($reservation['status'])) ?></span><h2><?= e($reservation['reference']) ?></h2><p><?= e($snapshot['location']['facility']??$reservation['facility_name']) ?><br><?= e(($snapshot['location']['floor']??$reservation['floor_label']).' · '.($snapshot['location']['slot']??$reservation['slot_label'])) ?></p><dl class="booking-details"><div><dt>Arrival</dt><dd><?= e($label($reservation['starts_at'])) ?></dd></div><div><dt>Departure estimate</dt><dd><?= e($label($reservation['ends_at'])) ?></dd></div><div><dt>Estimated total</dt><dd>₱<?= number_format((int)$reservation['estimated_centavos']/100,2) ?></dd></div></dl><p class="form-note">All times are Manila time. The estimate and cancellation rules were saved when this reservation was created.</p></article>
<article class="content-card"><h2><?= $live?'Your space is temporarily held.':'Reservation status' ?></h2>
<?php if ($live): ?><p>Hold expires at <?= e($label($reservation['expires_at'])) ?>.</p><p class="hold-clock" data-hold-expires="<?= e(str_replace(' ','T',$reservation['expires_at']).'Z') ?>" data-server-now="<?= e(str_replace(' ','T',$reservation['server_now']).'Z') ?>">Time remaining is checked by the server.</p><div class="notice">Payment integration is pending Phase 6. No payment has been collected. Your reservation remains pending and cannot be used for entry. No QR ticket or receipt has been issued.</div><a class="text-link" href="<?= e(url('reservation-checkout',['id'=>$reservation['id']])) ?>">Refresh status</a>
<?php elseif ($reservation['status']==='expired'): ?><p>The unpaid hold expired. The space is available for other eligible bookings. Choose a new space to try again.</p>
<?php elseif ($reservation['status']==='cancelled'): ?><p>This reservation was cancelled. Its temporary hold has been released.</p>
<?php elseif ($reservation['status']==='confirmed'): ?><p>This reservation is recorded as confirmed. QR access, provider reconciliation, and payment detail screens are implemented in later phases.</p>
<?php else: ?><p>This reservation is <?= e($reservation['status']) ?>. No live unpaid hold is shown.</p><?php endif; ?>
<?php if (in_array($reservation['status'],['pending','confirmed'],true)): ?><form class="account-form" method="post" action="<?= e(url('reservation-cancel')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$reservation['id'] ?>"><button class="button secondary" type="submit">Cancel reservation</button></form><?php endif; ?><a class="text-link" href="<?= e(url('facilities')) ?>">Explore parking</a></article></div>
<?php endif; ?></section>
